def insert_dash(num):
    s = str(num)
    result = []
    for i, ch in enumerate(s):
        digit = int(ch)
        result.append(ch)
        if i < len(s) - 1:
            next_digit = int(s[i + 1])
            if digit % 2 == 1 and next_digit % 2 == 1:
                result.append('-')
    return ''.join(result)
